use xiom.io;
fn print_greeting() {
  io.println("Welcome to the Calculator!");
}

fn add_numbers(a: Int, b: Int) -> Int {
  return a + b;
}

fn main() {
  print_greeting();
  let sum: Int = add_numbers(7, 8);
  io.println("Sum is 15");
}
